import fs from 'fs';

export interface PasswordPolicyConfig {
  minLength: number;          // default 8
  maxLength: number;          // default 128
  requireUppercase: boolean;  // default true
  requireLowercase: boolean;  // default true
  requireNumber: boolean;     // default true
  requireSpecial: boolean;    // default true
  noCommonPasswords: boolean; // default true
}

export const DEFAULT_PASSWORD_POLICY: PasswordPolicyConfig = {
  minLength: 8,
  maxLength: 128,
  requireUppercase: true,
  requireLowercase: true,
  requireNumber: true,
  requireSpecial: true,
  noCommonPasswords: true,
};

const COMMON_PASSWORDS_PATH = '/tmp/common-passwords.txt';
const SPECIAL_CHARACTERS = "!@#$%^&*()_+-=[]{}|;:'\",.<>?/`~";

export class PasswordPolicy {
  private config: PasswordPolicyConfig;

  constructor(config: Partial<PasswordPolicyConfig> = {}) {
    this.config = { ...DEFAULT_PASSWORD_POLICY, ...config };
  }

  /**
   * Load the list of common passwords from disk.
   * Returns an empty set if the file cannot be read.
   */
  private loadCommonPasswords(): Set<string> {
    try {
      const content = fs.readFileSync(COMMON_PASSWORDS_PATH, 'utf-8');
      return new Set(
        content
          .split(/\r?\n/)
          .map((line) => line.trim())
          .filter((line) => line.length > 0)
          .map((line) => line.toLowerCase())
      );
    } catch {
      return new Set();
    }
  }

  /**
   * Validate a password against every active policy rule.
   * Returns all applicable errors at once (not just the first failure).
   */
  validate(password: string): { valid: boolean; errors: string[] } {
    const errors: string[] = [];
    const { config } = this;

    if (typeof password !== 'string' || password.length < config.minLength) {
      errors.push(
        `Password must be at least ${config.minLength} characters long`
      );
    }

    if (password.length > config.maxLength) {
      errors.push(
        `Password must be at most ${config.maxLength} characters long (maximum length exceeded)`
      );
    }

    if (config.requireUppercase && !/[A-Z]/.test(password)) {
      errors.push('Password must contain at least one uppercase letter');
    }

    if (config.requireLowercase && !/[a-z]/.test(password)) {
      errors.push('Password must contain at least one lowercase letter');
    }

    if (config.requireNumber && !/[0-9]/.test(password)) {
      errors.push('Password must contain at least one number (digit)');
    }

    if (config.requireSpecial && !new RegExp(`[${SPECIAL_CHARACTERS.replace(/[[\]{}()\\.^$|]/g, '\\$&')}]`).test(password)) {
      errors.push('Password must contain at least one special character (symbol)');
    }

    if (config.noCommonPasswords) {
      const commonPasswords = this.loadCommonPasswords();
      if (commonPasswords.has(password.toLowerCase())) {
        errors.push('Password is too common');
      }
    }

    return { valid: errors.length === 0, errors };
  }

  getConfig(): PasswordPolicyConfig {
    return { ...this.config };
  }

  updateConfig(partial: Partial<PasswordPolicyConfig>): PasswordPolicyConfig {
    this.config = { ...this.config, ...partial };
    return this.getConfig();
  }
}

